import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading ensures availability before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type BaseballStatsCardProps = Record<string, any>;

const BaseballStatsCard: React.FC<BaseballStatsCardProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 12,
  cardBackgroundColor = "#1e293b",
  textColor = "#f8fafc",
  accentColor = "#ef4444",
  cardTitle = "SEASON STATS",
  statHTarget = 10,
  stat2BTarget = 7,
  stat3BTarget = 5,
  statHRStart = 3,
  statHRTarget = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parser safety: handle transparent background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling logic
  const contentWidth = width * 0.85;

  // Timing logic
  const totalFrames = durationInSeconds * fps;
  const entryDuration = fps * 1.5; // 1.5 seconds for entrance
  const exitDuration = fps * 1; // 1 second hold at the end
  
  // Distribute the remaining time equally among the 4 stats
  const availableCountingFrames = totalFrames - entryDuration - exitDuration;
  const timePerStat = Math.max(15, availableCountingFrames / 4);

  const t1 = entryDuration;
  const t2 = t1 + timePerStat;
  const t3 = t2 + timePerStat;
  const t4 = t3 + timePerStat;
  const t5 = t4 + timePerStat;

  // Entrance Animations
  const cardScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  const cardOpacity = interpolate(frame, [0, fps * 0.5], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Calculate values
  const countH = Math.floor(
    interpolate(frame, [t1, t2], [0, statHTarget], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const count2B = Math.floor(
    interpolate(frame, [t2, t3], [0, stat2BTarget], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const count3B = Math.floor(
    interpolate(frame, [t3, t4], [0, stat3BTarget], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const countHR = Math.floor(
    interpolate(frame, [t4, t5], [statHRStart, statHRTarget], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  // Helper for dynamic scaling during counting
  const getActiveScale = (start: number, end: number) => {
    return interpolate(
      frame,
      [start, start + fps * 0.2, end - fps * 0.2, end],
      [1, 1.15, 1.15, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  };

  const scaleH = getActiveScale(t1, t2);
  const scale2B = getActiveScale(t2, t3);
  const scale3B = getActiveScale(t3, t4);
  const scaleHR = getActiveScale(t4, t5);

  const getActiveColor = (start: number, end: number) => {
    return frame >= start && frame <= end ? accentColor : textColor;
  };

  // Icon animation
  const iconSpring = spring({ frame: frame - fps * 0.5, fps, config: { damping: 12 } });
  
  const iconRotation = interpolate(
    iconSpring,
    [0, 1],
    [-180, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
        }}
      >
        <div
          style={{
            width: contentWidth,
            backgroundColor: cardBackgroundColor,
            borderRadius: 40,
            padding: 50,
            display: "flex",
            flexDirection: "row", // Horizontal layout inside the card
            alignItems: "center",
            justifyContent: "space-between",
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
            transform: `scale(${cardScale})`,
            opacity: cardOpacity,
          }}
        >
          {/* Left Side: Icon Container */}
          <div
            style={{
              width: 220,
              height: 220,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              position: "relative",
              borderRight: `2px solid ${textColor}20`,
              paddingRight: 40,
            }}
          >
            <div
              style={{
                fontSize: 140,
                lineHeight: 1,
                transform: `scale(${iconSpring}) rotate(${iconRotation}deg)`,
                filter: `drop-shadow(0 10px 15px rgba(0,0,0,0.3))`,
              }}
            >
              ⚾
            </div>
          </div>

          {/* Right Side: Stats Container */}
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              paddingLeft: 40,
            }}
          >
            {/* Title */}
            <div
              style={{
                fontFamily: interFamily,
                fontSize: 32,
                fontWeight: 800,
                color: accentColor,
                letterSpacing: "0.1em",
                marginBottom: 40,
                textTransform: "uppercase",
              }}
            >
              {cardTitle}
            </div>

            {/* Stats Row */}
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "space-between",
                alignItems: "center",
                width: "100%",
              }}
            >
              {/* Column: H */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transform: `scale(${scaleH})`,
                }}
              >
                <span
                  style={{
                    fontFamily: interFamily,
                    fontSize: 36,
                    color: `${textColor}80`,
                    fontWeight: 600,
                    marginBottom: 10,
                  }}
                >
                  H
                </span>
                <span
                  style={{
                    fontFamily: robotoMonoFamily,
                    fontSize: 80,
                    color: getActiveColor(t1, t2),
                    fontWeight: 700,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {countH}
                </span>
              </div>

              {/* Column: 2B */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transform: `scale(${scale2B})`,
                }}
              >
                <span
                  style={{
                    fontFamily: interFamily,
                    fontSize: 36,
                    color: `${textColor}80`,
                    fontWeight: 600,
                    marginBottom: 10,
                  }}
                >
                  2B
                </span>
                <span
                  style={{
                    fontFamily: robotoMonoFamily,
                    fontSize: 80,
                    color: getActiveColor(t2, t3),
                    fontWeight: 700,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {count2B}
                </span>
              </div>

              {/* Column: 3B */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transform: `scale(${scale3B})`,
                }}
              >
                <span
                  style={{
                    fontFamily: interFamily,
                    fontSize: 36,
                    color: `${textColor}80`,
                    fontWeight: 600,
                    marginBottom: 10,
                  }}
                >
                  3B
                </span>
                <span
                  style={{
                    fontFamily: robotoMonoFamily,
                    fontSize: 80,
                    color: getActiveColor(t3, t4),
                    fontWeight: 700,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {count3B}
                </span>
              </div>

              {/* Column: HR */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  transform: `scale(${scaleHR})`,
                }}
              >
                <span
                  style={{
                    fontFamily: interFamily,
                    fontSize: 36,
                    color: `${textColor}80`,
                    fontWeight: 600,
                    marginBottom: 10,
                  }}
                >
                  HR
                </span>
                <span
                  style={{
                    fontFamily: robotoMonoFamily,
                    fontSize: 80,
                    color: getActiveColor(t4, t5),
                    fontWeight: 700,
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {countHR}
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BaseballStatsCard;